			memset(buf, 0, len);
			return len;
		}
		return -1;
	}
	size_t done = 0;
	while (done < len) {
		ssize_t r = pread(fd, buf + done, len - done, foffset + done);
		if (r < 0) {
			if (errno == EINTR) continue;
			close(fd);
			return -1;
