static int tree_depth(off_t size) {
	uint64_t blocks;
	uint64_t capacity = 1;
	int depth = 0;

	blocks = ((uint64_t)size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	do {
		depth++;
		capacity *= TREEDIRSIZE;
	} while (capacity < blocks);

	return depth;
}

void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	int depth;
	uint64_t block;
	int used;
	int level;
	int written;

	depth = tree_depth(size);
	block = (uint64_t)pos / TREEPAGESIZE;
	if (ppos)
		*ppos = pos % TREEPAGESIZE;

	used = strlen(name);
	for (level = depth - 1; level >= 0; level--) {
		uint64_t divisor = 1;
		int i;
		unsigned int index;

		for (i = 0; i < level; i++)
			divisor *= TREEDIRSIZE;
		index = (unsigned int)((block / divisor) % TREEDIRSIZE);
		written = snprintf(name + used, lenmax - used,
				   "/%s%04u", level > 0 ? "TREE" : "FILE", index);
		if (written < 0 || written >= lenmax - used)
			return; /* buffer too small, path truncated */
		used += written;
	}
}
