/*
 * Tree files support.
 *
 * When an export is configured with the treefiles option, the exported
 * block device is not backed by a single file, but by a tree of small
 * files, each holding at most TREEPAGESIZE bytes of device data. This
 * allows serving large virtual block devices on filesystems that do not
 * handle large files well.
 *
 * The device is divided into blocks of TREEPAGESIZE bytes. Every
 * directory in the tree holds at most TREEDIRSIZE entries, so the tree
 * is just deep enough to address all blocks of the device: for a device
 * of `size' bytes, block number `pos / TREEPAGESIZE' is written in base
 * TREEDIRSIZE with exactly as many digits as the tree is deep. All
 * digits except the last one name a subdirectory (TREEXXXX); the last
 * digit names the block file itself (FILEXXXX), e.g. for a tree two
 * levels deep block 1025 lives in <exportname>/TREE0001/FILE0001.
 *
 * Files and directories are created on demand when data is written to
 * them; a nonexistent block file reads as all zeroes. When a block is
 * trimmed in its entirety, its block file is deleted again.
 */

#include "lfs.h"
#include "config.h"
#include "nbd-debug.h"

#include <dirent.h>
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#include "treefiles.h"

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

/**
 * Calculate the number of levels the tree needs to hold a device of
 * the given size.
 *
 * @param size Total size of the exported device in bytes
 * @return Number of levels; 1 means all block files live directly in
 * the tree's root directory
 **/
static int tree_depth(off_t size) {
	uint64_t blocks;
	uint64_t capacity = 1;
	int depth = 0;

	blocks = ((uint64_t)size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	do {
		depth++;
		capacity *= TREEDIRSIZE;
	} while (capacity < blocks);

	return depth;
}

/**
 * Construct the path of the block file holding the data at a given
 * offset of the device.
 *
 * @param name On input, the root directory of the tree (i.e. the
 * exportname); on output, the full path of the block file, which will
 * be at most lenmax bytes long
 * @param lenmax Size of the name buffer
 * @param size Total size of the exported device in bytes
 * @param pos Byte offset into the device
 * @param ppos If not NULL, receives the offset into the block file
 * where the data for pos can be found
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	int depth;
	uint64_t block;
	int used;
	int level;

	depth = tree_depth(size);
	block = (uint64_t)pos / TREEPAGESIZE;
	if (ppos)
		*ppos = pos % TREEPAGESIZE;

	used = strlen(name);
	for (level = depth - 1; level >= 0; level--) {
		uint64_t divisor = 1;
		unsigned int index;
		int written;
		int i;

		for (i = 0; i < level; i++)
			divisor *= TREEDIRSIZE;
		index = (unsigned int)((block / divisor) % TREEDIRSIZE);
		written = snprintf(name + used, lenmax - used, "/%s%04u",
				   level > 0 ? "TREE" : "FILE", index);
		if (written < 0 || written >= lenmax - used)
			return;
		used += written;
	}
}

/**
 * Create all directories in the given path, like mkdir -p does.
 * Existing directories are silently left alone.
 *
 * @param path The directory path to create; temporarily modified
 **/
void mkdir_path(char *path) {
	char *p;

	p = path;
	if (*p == '/')
		p++;
	while ((p = strchr(p, '/')) != NULL) {
		*p = '\0';
		if (mkdir(path, 0700) < 0 && errno != EEXIST)
			DEBUG("Could not create directory %s: %s\n", path, strerror(errno));
		*p = '/';
		p++;
	}
	if (mkdir(path, 0700) < 0 && errno != EEXIST)
		DEBUG("Could not create directory %s: %s\n", path, strerror(errno));
}

/**
 * Open the block file holding the data at a given offset of the device.
 * When mode includes O_CREAT, any missing directories in the path are
 * created first.
 *
 * @param name The root directory of the tree (i.e. the exportname)
 * @param mode Open mode (O_RDONLY, O_RDWR, O_RDWR | O_CREAT, ...)
 * @param size Total size of the exported device in bytes
 * @param pos Byte offset into the device
 * @param mutex Lock serializing tree manipulation between threads
 * @return An open file descriptor, or -1 on error
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[PATH_MAX];
	char dir[PATH_MAX];
	char *slash;
	int len;
	int fd;

	len = snprintf(path, sizeof(path), "%s", name);
	if (len < 0 || len >= (int)sizeof(path))
		return -1;

	pthread_mutex_lock(mutex);
	construct_path(path, sizeof(path), size, pos, NULL);
	if (mode & O_CREAT) {
		snprintf(dir, sizeof(dir), "%s", path);
		slash = strrchr(dir, '/');
		if (slash != NULL) {
			*slash = '\0';
			mkdir_path(dir);
		}
	}
	fd = open(path, mode, 0600);
	pthread_mutex_unlock(mutex);

	return fd;
}

/**
 * Delete the block file holding the data at a given offset of the
 * device, so that the block reads as all zeroes again. If the file
 * does not exist, do nothing.
 *
 * @param name The root directory of the tree (i.e. the exportname)
 * @param size Total size of the exported device in bytes
 * @param pos Byte offset into the device
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	char path[PATH_MAX];
	int len;

	len = snprintf(path, sizeof(path), "%s", name);
	if (len < 0 || len >= (int)sizeof(path))
		return;
	construct_path(path, sizeof(path), size, pos, NULL);
	if (unlink(path) < 0 && errno != ENOENT)
		DEBUG("Could not delete block file %s: %s\n", path, strerror(errno));
}

/**
 * Recursively fsync all block files below the given directory.
 *
 * @param path Directory to flush
 * @return 0 on success, -1 on failure
 **/
static int flush_tree(const char *path) {
	DIR *dir;
	struct dirent *de;
	char child[PATH_MAX];
	int retval = 0;

	dir = opendir(path);
	if (!dir)
		return errno == ENOENT ? 0 : -1;
	while ((de = readdir(dir)) != NULL) {
		struct stat st;
		int fd;

		if (!strcmp(de->d_name, ".") || !strcmp(de->d_name, ".."))
			continue;
		if (snprintf(child, sizeof(child), "%s/%s", path, de->d_name)
				>= (int)sizeof(child)) {
			retval = -1;
			continue;
		}
		if (stat(child, &st) < 0) {
			retval = -1;
			continue;
		}
		if (S_ISDIR(st.st_mode)) {
			if (flush_tree(child) < 0)
				retval = -1;
		} else if (S_ISREG(st.st_mode)) {
			fd = open(child, O_RDONLY);
			if (fd < 0) {
				retval = -1;
				continue;
			}
			if (fsync(fd) < 0)
				retval = -1;
			close(fd);
		}
	}
	closedir(dir);

	return retval;
}

/**
 * Flush all data of a treefiles export to disk.
 *
 * @param name The root directory of the tree (i.e. the exportname)
 * @return 0 on success, -1 on failure
 **/
int flush_treefiles(char *name) {
	return flush_tree(name);
}

#ifndef NBD_TREEFILES_H
#define NBD_TREEFILES_H

#include "lfs.h"

#include <pthread.h>
#include <sys/types.h>

#define TREEDIRSIZE  1024 /**< number of files per subdirectory (or subdirs per subdirectory) */
#define TREEPAGESIZE 4096 /**< tree (block) files uses those chunks */

void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos);
void delete_treefile(char *name, off_t size, off_t pos);
int flush_treefiles(char *name);
void mkdir_path(char *path);
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex);

#endif

