Next, add tree helpers and hook them into rawexpread / rawexpwrite. Add two static helper functions before rawexpwrite, or right before rawexpread. Let's look for a good place to insert them: after the `complete_read` function and right before the doc comment of rawexpread. Actually, since these use open_treefile, let's put them right before rawexpread.

Tree read helper:

```c
/**
 * Read an amount of bytes at a given offset from the tree file that
 * holds that offset. Data that has never been written (i.e. for which
 * no block file exists) reads as zeroes.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an error
 **/
static ssize_t treeexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	off_t foffset;
	size_t maxbytes;
	ssize_t ret;
	size_t done = 0;
	int fhandle;

	maxbytes = TREEPAGESIZE - (size_t)(a % TREEPAGESIZE);
	if (len > maxbytes)
		len = maxbytes;
	foffset = a % TREEPAGESIZE;

	fhandle = open_treefile(client->exportname, O_RDONLY, client->exportsize, a, &client->tree_lock);
	if (fhandle < 0) {
		if (errno == ENOENT) {
			memset(buf, 0, len);
			return len;
		}
		return -1;
	}
	while (done < len) {
		ret = pread(fhandle, buf + done, len - done, foffset + done);
		if (ret < 0) {
			if (errno == EINTR)
				continue;
			close(fhandle);
			return -1;
		}
		if (ret == 0)
			break; /* end of file; remainder reads as zeroes */
		done += ret;
	}
	memset(buf + done, 0, len - done);
	close(fhandle);

	return len;
}
